#include <functional>
#include <memory>
#include <cstring>
#include <QGuiApplication>
#include <QQmlApplicationEngine>
#include <QCommandLineParser>
#include <QTimer>
#include <QLoggingCategory>
#include <QQuickWindow>
#include <QImage>
#include <QFile>
#include <QJsonDocument>

#include "watch.h"            // generated by qt_add_statecharts from statechart/watch.scxml
#include "ScxmlTreeModel.h"
#include "TransitionTracer.h"
#include "ButtonRouter.h"
#include "WatchModel.h"
#include "TimeoutService.h"
#include "Beeper.h"
#include "SpecTags.h"

int main(int argc, char *argv[])
{
    // --no-gui: no window, no QML, no platform plugin (QCoreApplication). The
    // statechart, clock, input path (ButtonRouter), event log and --script run as
    // usual. tools/verify.py uses it: the walk checks behaviour, not rendering.
    // It must be known before the application object exists, so look for it here;
    // QCommandLineParser below documents and validates it.
    bool noGui = false;
    for (int i = 1; i < argc; ++i)
        if (std::strcmp(argv[i], "--no-gui") == 0)
            noGui = true;
    // https://doc.qt.io/qt-6/qcoreapplication.html (no GUI) vs.
    // https://doc.qt.io/qt-6/qguiapplication.html (loads the platform plugin)
    const std::unique_ptr<QCoreApplication> appPtr(noGui ? new QCoreApplication(argc, argv)
                                                         : new QGuiApplication(argc, argv));
    QCoreApplication &app = *appPtr;
    // <log> elements are spec-row markers for TransitionTracer, not console output.
    QLoggingCategory::setFilterRules(QStringLiteral("scxml.statemachine.debug=false"));
    app.setApplicationName(QStringLiteral("watch-me"));

    QCommandLineParser cli;
    cli.setApplicationDescription(QStringLiteral("Harel's 1987 watch statechart, executable."));
    cli.addHelpOption();
    QCommandLineOption autoInsert(QStringLiteral("auto-insert"), QStringLiteral("Insert the battery at start-up."));
    cli.addOption(autoInsert);
    QCommandLineOption script(QStringLiteral("script"),
        QStringLiteral("Semicolon separated steps run after start-up: 'a' (click), '+a'/'-a' (hold/release), "
                       "'wait:ms', or any SCXML event name."), QStringLiteral("steps"));
    QCommandLineOption grab(QStringLiteral("grab"), QStringLiteral("Save a screenshot of the window to <file> and quit."),
                            QStringLiteral("file"));
    QCommandLineOption grabDelay(QStringLiteral("grab-delay"), QStringLiteral("Delay before --grab (ms)."),
                                 QStringLiteral("ms"), QStringLiteral("800"));
    QCommandLineOption startTime(QStringLiteral("time"),
        QStringLiteral("Clock value set when the battery is inserted (ISO 8601, e.g. 1987-06-01T10:08:30)."),
        QStringLiteral("datetime"));
    cli.addOption(startTime);
    QCommandLineOption winSize(QStringLiteral("size"), QStringLiteral("Window size, e.g. 1920x1080."),
                               QStringLiteral("WxH"));
    cli.addOption(winSize);
    cli.addOption(script);
    QCommandLineOption manualTime(QStringLiteral("manual-time"),
        QStringLiteral("Time does not follow the real clock; only --script steps 'clock:ms' and "
                       "'advance:ms' move the watch time and the statechart's timeouts."));
    cli.addOption(manualTime);
    QCommandLineOption exitAfter(QStringLiteral("exit"), QStringLiteral("Quit when the --script has run."));
    cli.addOption(exitAfter);
    cli.addOption(grab);
    cli.addOption(grabDelay);
    QCommandLineOption noGuiOption(QStringLiteral("no-gui"),
        QStringLiteral("No window: run the statechart, input path, event log and --script only "
                       "(used by tools/verify.py). Not with --grab, --size or 'select:' steps."));
    cli.addOption(noGuiOption);
    cli.process(app);
    if (noGui && (cli.isSet(grab) || cli.isSet(winSize))) {
        qCritical("watch-me: --grab and --size need the window; they cannot be used with --no-gui.");
        return 1;
    }

    WatchMachine machine;
    // The ecmascript datamodel is a Qt SCXML plugin; without it every condition and
    // timer in watch.scxml fails. Say so instead of misbehaving.
    if (!machine.dataModel()) {
        qCritical("watch-me: Qt SCXML's ECMAScript datamodel plugin (plugins/scxmldatamodel) "
                  "was not found; the installation is incomplete.");
        return 2;
    }
    ScxmlTreeModel tree;
    tree.load(QStringLiteral(":/statechart/watch.scxml"));
    SpecTags specTags;
    specTags.load(QStringLiteral(":/docs/STATECHART-SPEC.md"));
    TransitionTracer tracer(&machine, &tree);
    WatchModel watch(&machine);
    TimeoutService timeouts(&machine);      // the statechart's "n sec in X" timers, 1x real time
    if (!cli.isSet(manualTime)) {
        watch.setRunning(true);
        timeouts.setRunning(true);
    }
    if (cli.isSet(startTime))
        watch.setResetTime(QDateTime::fromString(cli.value(startTime), Qt::ISODate));
    ButtonRouter buttons(&machine);
    Beeper beeper;
    QObject::connect(&watch, &WatchModel::shortBeep, &beeper, &Beeper::shortBeep);
    buttons.setTracer(&tracer);

    std::unique_ptr<QQmlApplicationEngine> engine;
    if (!noGui) {
        engine = std::make_unique<QQmlApplicationEngine>();
        QVariantMap layout;
        {
            QFile lf(QStringLiteral(":/statechart/layout.json"));
            if (lf.open(QIODevice::ReadOnly))
                layout = QJsonDocument::fromJson(lf.readAll()).toVariant().toMap();
        }
        // Main.qml's required properties: the host contract (docs/HOST-CONTRACT.md).
        // https://doc.qt.io/qt-6/qqmlapplicationengine.html#setInitialProperties
        engine->setInitialProperties({
            {QStringLiteral("tree"), QVariant::fromValue<QObject *>(&tree)},
            {QStringLiteral("tracer"), QVariant::fromValue<QObject *>(&tracer)},
            {QStringLiteral("buttons"), QVariant::fromValue<QObject *>(&buttons)},
            {QStringLiteral("watch"), QVariant::fromValue<QObject *>(&watch)},
            {QStringLiteral("beeper"), QVariant::fromValue<QObject *>(&beeper)},
            {QStringLiteral("specTags"), QVariant::fromValue<QObject *>(&specTags)},
            {QStringLiteral("appLayout"), layout},
        });

        QObject::connect(engine.get(), &QQmlApplicationEngine::objectCreationFailed, &app,
                         [] { QCoreApplication::exit(1); }, Qt::QueuedConnection);
        // Main.qml by module URI and type name, wherever the module's resource prefix is.
        // https://doc.qt.io/qt-6/qqmlapplicationengine.html#loadFromModule
        engine->loadFromModule(QStringLiteral("WatchMe"), QStringLiteral("Main"));

        if (cli.isSet(winSize)) {
            const QStringList wh = cli.value(winSize).split(QLatin1Char('x'));
            if (auto *w = qobject_cast<QQuickWindow *>(engine->rootObjects().value(0)); w && wh.size() == 2)
                w->resize(wh[0].toInt(), wh[1].toInt());
        }
    }
    machine.start();
    if (cli.isSet(autoInsert))
        QTimer::singleShot(0, &buttons, [&] { buttons.submit(QStringLiteral("battery.inserted")); });

    // Scripted interaction + screenshot, used for docs/screenshots (QQuickWindow::grabWindow).
    QStringList steps = cli.value(script).split(QLatin1Char(';'), Qt::SkipEmptyParts);
    const QString grabFile = cli.value(grab);
    const int delay = cli.value(grabDelay).toInt();
    std::function<void()> runNext;
    runNext = [&] {
        if (steps.isEmpty()) {
            if (cli.isSet(exitAfter) && grabFile.isEmpty())
                QTimer::singleShot(delay, &app, &QCoreApplication::quit);
            if (!grabFile.isEmpty())
                QTimer::singleShot(delay, &app, [&] {
                    auto *w = qobject_cast<QQuickWindow *>(engine->rootObjects().value(0));
                    if (w && !w->grabWindow().save(grabFile))
                        qWarning("could not save %s", qPrintable(grabFile));
                    QCoreApplication::quit();
                });
            return;
        }
        const QString s = steps.takeFirst().trimmed();
        int gap = 60;
        const QStringList parts = s.split(QLatin1Char(':'));
        if (s.startsWith(QLatin1String("wait:"))) {
            gap = s.mid(5).toInt();
        } else if (parts.first() == u"alarm" && parts.size() == 4) {        // alarm:1:07:15
            watch.setAlarm(parts[1].toInt(), parts[2].toInt() * 60 + parts[3].toInt());
        } else if (parts.first() == u"jump" && parts.size() == 3) {         // jump:1:5  (T1 - 5 s)
            watch.jumpBeforeAlarm(parts[1].toInt(), parts[2].toInt());
        } else if (parts.first() == u"settime" && parts.size() == 4) {      // settime:10:59:58
            watch.setTime(parts[1].toInt(), parts[2].toInt(), parts[3].toInt());
        } else if (parts.first() == u"advance" && parts.size() == 2) {      // advance:120000 (timeout clock, ms)
            timeouts.advance(parts[1].toLongLong());
        } else if (parts.first() == u"clock" && parts.size() == 2) {        // clock:2000 (watch time T, ms)
            watch.advance(parts[1].toLongLong());
        } else if (parts.first() == u"speed" && parts.size() == 2) {
            watch.setSpeed(parts[1].toDouble());
        } else if (s.startsWith(QLatin1String("export:"))) {              // export:/path/log.txt
            // the rest of the step, whole: a Windows path has a ':' of its own (C:\...)
            if (!tracer.exportLog(s.mid(7)))
                qWarning("could not export the log to %s", qPrintable(s.mid(7)));
        } else if (parts.first() == u"select" && parts.size() == 2) {       // select:time (statechart view)
            if (!engine)
                qWarning("watch-me: 'select:' needs the window; ignored with --no-gui");
            else if (auto *root = engine->rootObjects().value(0))
                if (auto *v = root->findChild<QObject *>(QStringLiteral("statechartView")))
                    v->setProperty("selected", parts[1]);
        } else if (parts.first() == u"set" && parts.size() == 3) {          // set:harelAnomalies:false
            const QVariant v = parts[2] == u"true" ? QVariant(true)
                             : parts[2] == u"false" ? QVariant(false) : QVariant(parts[2].toDouble());
            buttons.setDataValue(parts[1], v);          // keeps the sim panel in sync
        } else if (s.size() == 1) {
            buttons.press(s);
            QTimer::singleShot(30, &buttons, [&buttons, s] { buttons.release(s); });
        } else if (s.size() == 2 && s[0] == u'+') {
            buttons.press(s.mid(1));
        } else if (s.size() == 2 && s[0] == u'-') {
            buttons.release(s.mid(1));
        } else {
            buttons.submit(s);
        }
        QTimer::singleShot(gap, &app, runNext);
    };
    QTimer::singleShot(200, &app, runNext);
    return app.exec();
}
